varA = int(input("Gib die erste ganze Zahl ein: "))
varB = int(input("Gib die zweite ganze Zahl ein: "))

if varA > varB:
    print("A größer B")
elif varA < varB:
    print ("A kleiner B")
else:
    print("Beide Zahlen gleich")
    